/* One problem, on the node and pin that caused it. */
struct de_ep_material_graph_diagnostic {
    de_ep_material_graph_severity severity;
    de_ep_str node; /* node path ("n3", or "n4/n2" inside subgraph n4); empty for the whole graph or generated boilerplate */
    de_ep_str pin; /* the pin, or empty */
    de_ep_str message;
    bool has_line;
    uint32_t line; /* one-based line in the graph file; omitted when unknown */
};

/* Where an exposed parameter lives in the material's float4 rows or texture slots, and its default. */
struct de_ep_material_graph_param {
    de_ep_material_graph_param_kind kind;
    de_ep_str name;
    de_ep_str node; /* the first node that declares it */
    uint32_t row; /* FLOAT and COLOR: float4 row 0..9 */
    uint32_t component; /* FLOAT and COLOR: first component 0..3 */
    uint32_t slot; /* TEXTURE: slot 0..18 */
    de_ep_list_f32 value; /* the default: 1 value (FLOAT) or 3 (COLOR); empty for TEXTURE */
    float min;
    float max;
};

/* A material graph file's text (TOML, kind = "material", version = 1), usually the unsaved editor buffer. */
struct de_ep_material_graph_params {
    de_ep_str graph; /* the graph file text, at most 4 MiB */
    bool has_name;
    de_ep_str name; /* a name for the generated module's header comment */
};

struct de_ep_material_graph_target_result {
    de_ep_str target;
    de_ep_material_graph_target_status status; /* UNSUPPORTED: this engine build cannot compile for the target */
    bool has_code_size;
    uint64_t code_size; /* bytes of compiled code when OK */
    de_ep_list_material_graph_diagnostic diagnostics; /* Slang errors and warnings mapped to graph nodes */
    bool has_message;
    de_ep_str message; /* Slang's unmapped diagnostics text, possibly cut */
};

/* Saved source-mode material rendered in an isolated preview world; no material edits or game-world mutation. */
struct de_ep_material_render_params {
    de_ep_str id; /* Manifest material asset ID, not a model ID. */
    de_ep_str shape; /* sphere, box or plane; fixed bounded preview geometry. */
    float yaw; /* Camera degrees about +Z. */
    uint32_t size; /* Square PNG edge in pixels, 1..1024. */
    bool has_revision;
    uint32_t revision; /* Opaque caller cache token. Change after observed source/dependency edits to invalidate the private preview before its next cook; not a content hash. Absent uses engine source-watch invalidation. */
};

struct de_ep_model_attribute {
    de_ep_str name; /* position, normal, tangent, uv0, uv1, color, joints, weights */
    de_ep_str format; /* as cooked: f32x3, snorm16x3, unorm16x2, ... */
};

/* A cooked model as the model viewer shows it (DIDE-R163). */
struct de_ep_model_info {
    de_ep_list_model_node nodes;
    de_ep_list_model_lod lods;
    de_ep_list_model_attribute attributes;
    uint32_t uv_sets;
    de_ep_list_f32 bounds_min;
    de_ep_list_f32 bounds_max;
    de_ep_list_model_node bones; /* the skeleton, by parent index; empty without one */
    de_ep_list_model_slot slots;
};

struct de_ep_model_inspect_params {
    de_ep_str id;
    uint32_t mesh; /* Index into meshes. Zero also queries a model containing no meshes. */
};

/* Complete node/mesh references plus one mesh's actual cooked metadata, gated by assets.modelInspection. At most 8192 nodes, 1024 mesh IDs, 4096 submeshes and 8 LODs; oversized models return an explicit error rather than partial metadata. */
struct de_ep_model_inspection {
    de_ep_list_model_node nodes;
    de_ep_list_model_node bones; /* Existing skeleton summary when available; empty is not proof the source has no skin. */
    de_ep_list_str meshes; /* Actual mesh asset IDs in model order; node.mesh references one of these. */
    bool has_mesh;
    uint32_t mesh; /* Selected index; absent only when meshes is empty. */
    uint32_t vertices;
    de_ep_list_model_mesh_lod lods;
    de_ep_list_model_attribute attributes;
    de_ep_list_u32 uv_channels; /* Actual channel indices, including sparse UV1-only layouts. */
    de_ep_list_f32 bounds_min;
    de_ep_list_f32 bounds_max;
    de_ep_list_f32 position_offset;
    de_ep_list_f32 position_scale;
    float max_position_error; /* Configured maximum permitted position-quantization error in object-space metres (import budget, not measured error). */
    de_ep_list_model_submesh submeshes;
};

struct de_ep_model_lod {
    uint32_t triangles;
    uint32_t meshlets;
    float screen_error; /* the screen-space error it switches at (the model's lod_error scaled per LOD) */
};

struct de_ep_model_mesh_lod {
    uint32_t triangles;
    uint32_t meshlets;
    uint32_t vertices;
    float error_metres; /* Actual cooked object-space simplification error; zero for LOD 0. Not a camera switch distance. */
};

struct de_ep_model_node {
    de_ep_str name;
    bool has_parent;
    uint32_t parent; /* index into nodes */
    bool has_mesh;
    de_ep_str mesh; /* the mesh sub-asset it places */
};

struct de_ep_model_render_params {
    de_ep_str id;
    uint32_t lod;
    de_ep_str overlay; /* none, wireframe, meshlets, uv0, uv1, skeleton, bounds */
    float yaw; /* degrees about +Z (the turntable) */
    uint32_t size;
    bool has_mesh;
    uint32_t mesh; /* Mesh index from modelInspect when selecting an individual mesh; absent preserves whole-model legacy previews. */
    bool has_revision;
    uint32_t revision; /* Opaque caller source-generation token. With assets.modelPreviewRevision, a changed token forces a fresh model context; equal tokens reuse it across angles. Omit for legacy peers. */
};

struct de_ep_model_slot {
    de_ep_str name;
    de_ep_str material; /* the material sub-asset or asset ID it uses */
};

struct de_ep_model_submesh {
    de_ep_str material; /* Assigned material asset ID; empty selects the engine default. */
    de_ep_list_f32 bounds_min;
    de_ep_list_f32 bounds_max;
    de_ep_list_model_submesh_lod lods;
};

struct de_ep_model_submesh_lod {
    uint32_t index_first; /* First index in the cooked mesh's combined LOD index buffer. */
    uint32_t index_count;
    uint32_t meshlet_first; /* First meshlet in the cooked mesh's combined LOD meshlet table. */
    uint32_t triangles;
    uint32_t meshlets;
};

